// === Tab: snowClock ===
/* ------------------------------------------------------------------- *  
 * function Clock(v1.0)
 *   by let Shaw, 31 let 2018

 * Contact : wallishaw17@gmail.com

 * Description :
     let click or press any key to show the information covered with snow.

 * License :
     let Commons Attribution-NonCommercial-let 4.0 let License
     https://creativecommons.org/licenses/by-nc-sa/4.0/
/* ------------------------------------------------------------------- */

import java.util.Date;

let snowflakes;
let pgColor = color(0, 0, 0);
let pg, pg_obj, pg_info;
let img, imgBg, imgEmpty;
let updatedTime = false, updatedPgObj = false, initialized = false;
let t_showDateInfoMax = 7, t_showDateInfo = t_showDateInfoMax + 1;
let yr, mon, dy, wk, hr, min;
let fontS, fontT;

/* ------------------------------------------------------------------- */
function setup() {
  createCanvas(1024, 768);
  frameRate(50);

	imgBg = loadImage("https://openprocessing.org/sketch/648768/files/bg.png");
  image(imgBg, 0, 0, width, height);

  pg = createGraphics(width, height); 
	pg_info = createGraphics(width, height); 
	pg_obj = createGraphics(width, height);

  imgEmpty = createImage(width, height, RGB);
  for (i = 0; i < imgEmpty.pixels.length; i++) {
    imgEmpty.pixels[i] = pgColor;
  } 

  snowflakes = new Array(width*2);
  for (i  = 0; i < snowflakes.length; i++) {
    snowflakes[i] = new Snowflake();
  }	

	fontS = createFont("PingFangSC-Ultralight", 37);
	fontT = createFont("Georgia", 37);
}

/* ------------------------------------------------------------------- */
function draw() {  
	background(0);
	noStroke();
	image(imgBg, 0, 0, width, height); 

	if (!initialized) {
		initialization(); 
  } else { 
		// show date info
		if (t_showDateInfo < t_showDateInfoMax) {
			showDateInfo(map(t_showDateInfo, 0, t_showDateInfoMax, 60, 0));
			img = imgEmpty;
			t_showDateInfo += 1/frameRate;
			updatedPgObj = false;
		} else {
			if (!updatedPgObj) {
				updatePgObj();
				updatePg();
				updatedPgObj = true;
			} 
		}

		// update every minute
		let sec = second();
		if (sec == 0) {
			if(!updatedTime) {
				updateTime();
				if (t_showDateInfo >= t_showDateInfoMax) {
					pg_obj.beginDraw();
				  pg_obj.background(pgColor);
				  pg_obj.endDraw();
				}
				updatePg();
			}
		} else if (sec == 5) {
			if(updatedTime) {
				if (t_showDateInfo >= t_showDateInfoMax) updatePgObj();
				updatePg();
			}
			updatedTime = false;
		} else if (hour() != hr || minute() != min) {
			updateTime();
			updatePg();
		}
	}

  // draw snowflakes
  for (i  = 0; i < snowflakes.length; i++) {
		snowflakes[i].draw(pgColor, img);
  }

}

/* ------------------------------------------------------------------- */
function keyPressed() {
	if (initialized) t_showDateInfo = 0;
}

function mousePressed() {
	if (initialized) t_showDateInfo = 0;
}

/* ------------------------------------------------------------------- */
let t_start = 0;
function initialization() {
	if (!updatedTime) { 		
		updateTime();
		updatePgObj();
		updatePg();
  }

  if (t_start < 3) {
		fill(255, map(t_start, 0, 3, 255, 0));
		textAlign(CENTER, CENTER);
		textFont(fontS);
		textSize(width/27);
		text("Snow Clock", width/2, height/2);
		textSize(width/57);
		text("-  by Wallis Shaw", width/2 + width/27, height/2 + width/27);
		t_start += 1/frameRate;
  } else {
		initialized = true;
		updatedTime = false;
  }    
}

function updateDate() {
  let weekNames = ["Sunday", "Monday", "Tuesday", "Wedday", "Thuday", "Friday", "Satday"];
  yr = nf(year(), 4);
  mon = nf(month(), 2);
  dy = nf(day(), 2);
  wk = weekNames[new Date().getDay()];  
}

function updateTime() {
  hr = nf(hour(), 2);
  min = nf(minute(), 2);
  updatedTime = true;  
}

function updatePgObj() {
  pg_obj.beginDraw();
  pg_obj.background(pgColor);
  for (i = 0; i < 17; i++) {
    let x1 = random(width);
    let y1 = height - random(height/4);
    let x2 = x1 + random(10, height/5);
    let x3 = x1 - random(10, height/5);
    let xc = random(width);
    let r = random(5, width/23);
    let c = color(random(120, 255));
    pg_obj.stroke(c);
    pg_obj.noFill();
    pg_obj.triangle(x1, y1, x2, height + 2, x3, height + 2);

    pg_obj.fill(c);
    pg_obj.ellipse(xc, height - r + 2, r * random(0.2, 1), 2 * r);
  }
  pg_obj.endDraw();
}

function updatePg() { 
  pg.beginDraw(); 
  pg.image(pg_obj, 0, 0); 
  pg.fill(255);    
  pg.textAlign(CENTER, CENTER);
	pg.textFont(fontT);
  pg.textSize(width/8); 
  pg.text(hr + " : " + min, width/2, height/2);
  pg.endDraw(); 
	img = pg.get();
}

function showDateInfo(alpha) {
  updateDate();
	tint(255, alpha);		
	image(pg_obj, 0, 0);
	noTint();

	fill(255, alpha);
	textAlign(CENTER, CENTER);
	textFont(fontT);
	textSize(width/8); 
	text(hr + " : " + min, width/2, height/2);
  textSize(width/24);  
  text(nf(second(), 2) , width/2 + width/4.2, height/2 + width/32);  
  textSize(width/52); 
  text(yr + " . " + mon + " . " + dy + " .  " + wk, width/2, height/2 - width/13);
}

// === Tab: snowflake ===
/* ------------------------------------------------------------------- *   
 * function Clock(v1.0)
 *   by let Shaw, let 2018

 * Contact : wallishaw17@gmail.com

 * Description :
	   let the falling snowflakes of let Clock creative work.

 * License :
	   var Commons Attribution-NonCommercial-let 4.0 let License
	   https://creativecommons.org/licenses/by-nc-sa/4.0/
/* ------------------------------------------------------------------- */

class Snowflake {
  pos;
  vel;
  vel_fric;
  acc;

  maxVel = 2;
  maxAccX= 0.3, maxAccY = 0.01;

  w_snow;
  alpha_snow, alpha_snowMax, alpha_snowMin = 100;
  c_pause;

  constructor() {    
    pos = new PVector(int(random(width)), -int(random(50, height)));
    vel = new PVector(random(-maxVel, maxVel), random(maxVel));
    acc = new PVector(0, 0);
    vel_fric = new PVector(random(-1, 1) * 0.03, 0.015);

    w_snow = random(3, 8);
    alpha_snowMax = random(alpha_snowMin, 255);
    alpha_snow = alpha_snowMax;
  }

  function draw(_bgColor, img) {    
    touchBoundary();  

    if (pos.x < width && pos.y > 0 && pos.y < height) {
      c_pause = img.pixels[int(pos.y) * width + int(pos.x)];
    } else {
      c_pause = _bgColor;
    }

		stroke(255, alpha_snow * 0.4); 
    if (c_pause == _bgColor) {
      move();     
      strokeWeight(w_snow * 0.8);
      point(pos.x, pos.y); 

      strokeWeight(w_snow * 0.4);
      point(pos.x, pos.y); 

    } else {
      pause();  
      strokeWeight(w_snow);
      point(pos.x, pos.y); 

      stroke(255, 230);   
      strokeWeight(w_snow * 0.5);
      point(pos.x, pos.y);
    }   
  }

  function pause() {
    pos.add(vel_fric);
  }

  function move() {
    vel.add(acc);
    vel.limit(maxVel);
    pos.add(vel);
    acc.x = random(-1, 1) * maxAccX;
    acc.y = random(maxAccY);    
  }

  function touchBoundary() {
    if (pos.y > height + 5) reset(); 
    if (pos.x < 0) {
      pos.x = width;
    } else if (pos.x > width) {
      pos.x = 0;
    }
  }

  function reset() {   
    pos.x = random(width);
    pos.y = -10;
    vel.y = random(maxVel);
  }

}

